export async function test_api_inventory_ownership_validation(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Administrator setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {});
  const category =
    await generate_random_shopping_mall_administrator_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // Step 2: Seller A setup - register and login
  const sellerAConnection: api.IConnection = { host: connection.host };
  const sellerA = await authorize_seller_join(sellerAConnection, {
    body: {
      shop_name: "Seller A Shop",
    },
  });
  typia.assert(sellerA);
  // Step 3: Seller A creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerAConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        categoryId: category.id,
        basePrice: typia.random<
          number & tags.Minimum<1000> & tags.Maximum<100000>
        >(),
      },
    },
  );
  typia.assert(product);
  // Step 4: Seller A creates variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerAConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          optionValues: { color: "Red", size: "Large" },
          price: typia.random<
            number & tags.Minimum<1000> & tags.Maximum<100000>
          >(),
        },
      },
    );
  typia.assert(variant);
  // Step 5: Seller A adds initial inventory to their variant
  const initialInventory =
    await generate_random_shopping_mall_seller_variants_inventory_records_create(
      sellerAConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantity_change: 100,
          reason: "Initial stock from supplier",
        },
      },
    );
  typia.assert(initialInventory);
  // Step 6: Seller B setup - register and login (different seller)
  const sellerBConnection: api.IConnection = { host: connection.host };
  const sellerB = await authorize_seller_join(sellerBConnection, {
    body: {
      shop_name: "Seller B Shop",
    },
  });
  typia.assert(sellerB);
  // Step 7: Seller B attempts to create inventory record for Seller A's variant
  // This should fail with 403 Forbidden (ownership violation)
  await TestValidator.httpError(
    "Seller B cannot adjust Seller A's inventory",
    403,
    async () => {
      await generate_random_shopping_mall_seller_variants_inventory_records_create(
        sellerBConnection,
        {
          params: { variantId: variant.id },
          body: {
            quantity_change: 50,
            reason: "Unauthorized inventory adjustment attempt",
          },
        },
      );
    },
  );
}

