export async function test_api_cart_item_quantity_update_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {});
  const category =
    await generate_random_shopping_mall_administrator_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // 2. Seller setup - create product, variant, and inventory
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
        basePrice: typia.random<
          number & tags.Minimum<1000> & tags.Maximum<10000>
        >(),
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: RandomGenerator.alphaNumeric(8).toUpperCase(),
          optionValues: { color: "Red", size: "M" },
          price: typia.random<
            number & tags.Minimum<1000> & tags.Maximum<5000>
          >(),
        },
      },
    );
  typia.assert(variant);
  // Add inventory with sufficient stock (more than we'll request)
  const inventoryQuantity = 100;
  const inventory =
    await generate_random_shopping_mall_seller_variants_inventory_records_create(
      sellerConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantity_change: inventoryQuantity,
          reason: "Initial stock for testing",
        },
      },
    );
  typia.assert(inventory);
  // 3. Customer setup - create cart item
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const initialQuantity = 2;
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          variant_id: variant.id,
          quantity: initialQuantity,
        },
      },
    );
  typia.assert(cartItem);
  // Store initial timestamp for comparison
  const initialUpdatedAt = cartItem.updated_at;
  const cartItemId = cartItem.id;
  // Wait briefly to ensure timestamp difference
  await new Promise((resolve) => setTimeout(resolve, 100));
  // 4. First update - increase quantity
  const increasedQuantity = 5;
  const updatedItem1 =
    await api.functional.shoppingMall.customer.cart.items.patch(
      customerConnection,
      {
        body: {
          quantity: increasedQuantity,
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedItem1);
  // 5. Verify first update
  const expectedPrice = variant.price ?? product.base_price;
  const expectedSubtotal = expectedPrice * increasedQuantity;
  TestValidator.equals(
    "cart item ID remains same",
    updatedItem1.id,
    cartItemId,
  );
  TestValidator.equals(
    "quantity updated to increased value",
    updatedItem1.quantity,
    increasedQuantity,
  );
  TestValidator.equals("price is correct", updatedItem1.price, expectedPrice);
  TestValidator.equals(
    "subtotal is correctly calculated",
    updatedItem1.subtotal,
    expectedSubtotal,
  );
  TestValidator.equals(
    "stock_warning is false (within stock)",
    updatedItem1.stock_warning,
    false,
  );
  TestValidator.equals("unavailable is false", updatedItem1.unavailable, false);
  TestValidator.predicate(
    "updated_at timestamp refreshed",
    updatedItem1.updated_at !== initialUpdatedAt,
  );
  // Store timestamp for second update comparison
  const firstUpdatedAt = updatedItem1.updated_at;
  // Wait briefly to ensure timestamp difference
  await new Promise((resolve) => setTimeout(resolve, 100));
  // 6. Second update - decrease quantity
  const decreasedQuantity = 3;
  const updatedItem2 =
    await api.functional.shoppingMall.customer.cart.items.patch(
      customerConnection,
      {
        body: {
          quantity: decreasedQuantity,
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedItem2);
  // 7. Verify second update
  const expectedSubtotal2 = expectedPrice * decreasedQuantity;
  TestValidator.equals(
    "cart item ID remains same after second update",
    updatedItem2.id,
    cartItemId,
  );
  TestValidator.equals(
    "quantity updated to decreased value",
    updatedItem2.quantity,
    decreasedQuantity,
  );
  TestValidator.equals(
    "price remains correct",
    updatedItem2.price,
    expectedPrice,
  );
  TestValidator.equals(
    "subtotal recalculated correctly",
    updatedItem2.subtotal,
    expectedSubtotal2,
  );
  TestValidator.equals(
    "stock_warning remains false",
    updatedItem2.stock_warning,
    false,
  );
  TestValidator.equals(
    "unavailable remains false",
    updatedItem2.unavailable,
    false,
  );
  TestValidator.predicate(
    "updated_at timestamp refreshed again",
    updatedItem2.updated_at !== firstUpdatedAt,
  );
}

