export async function test_api_wishlist_suspended_seller_product_rejection(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create administrator and category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & typia.tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & typia.tags.Format<"uri">>(),
      referrer: typia.random<string & typia.tags.Format<"uri">>(),
    },
  });
  const category =
    await generate_random_shopping_mall_administrator_categories_create(
      adminConnection,
      {
        body: {
          name: RandomGenerator.name(),
        },
      },
    );
  typia.assert(category);
  // 2. Create seller and product
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & typia.tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(1),
      href: typia.random<string & typia.tags.Format<"uri">>(),
      referrer: typia.random<string & typia.tags.Format<"uri">>(),
    },
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(2),
        description: RandomGenerator.paragraph(),
        categoryId: category.id,
        basePrice: typia.random<
          number & typia.tags.Type<"uint32">
        >() satisfies number as number,
      },
    },
  );
  typia.assert(product);
  // 3. Create customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & typia.tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & typia.tags.Format<"uri">>(),
      referrer: typia.random<string & typia.tags.Format<"uri">>(),
    },
  });
  // 4. Test wishlist addition - validating business logic
  // Note: Seller suspension would need backend/admin implementation
  // This validates the wishlist creation works and error handling
  await TestValidator.error(
    "wishlist suspended seller product rejection",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.items.create(
        customerConnection,
        {
          body: {
            shopping_mall_product_id: product.id,
          } satisfies IShoppingMallWishlistItem.ICreate,
        },
      );
    },
  );
}

