      },
    );
  typia.assert(filteredSnapshots);
  // 12. Verify only snapshot for refund request #1 is returned
  TestValidator.predicate(
    "filtered snapshots should only contain snapshots for refund request #1",
    filteredSnapshots.data.every(
      (snapshot) => snapshot.refundRequest.id === refundRequest1.id,
    ),
