  typia.assert(paginatedResult);
  TestValidator.equals(
    "pagination current page should be 1",
    paginatedResult.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination limit should be respected",
    paginatedResult.pagination.limit === 10,
  );
  // 14. Verify all returned snapshots have the correct refund request ID
  for (const snapshot of filteredSnapshots.data) {
    TestValidator.equals(
      "snapshot refund request ID should match filter",
      snapshot.refundRequest.id,
      refundRequest1.id,
    );
  }
}

