export async function test_api_review_snapshot_deleted_review_preservation(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Setup Administrator
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_administrator_join(adminConnection, {});
  typia.assert(admin);
  // Step 2: Setup Seller and create product
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  typia.assert(seller);
  // Seller creates product (seller needs to be approved for this)
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // Step 3: Setup Customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  typia.assert(customer);
  // Step 4: Customer creates address and order
  const address = await generate_random_shopping_mall_customer_addresses_create(
    customerConnection,
    {},
  );
  typia.assert(address);
  const order = await generate_random_shopping_mall_customer_checkout_create(
    customerConnection,
    { body: { address_id: address.id } },
  );
  typia.assert(order);
  // Step 5: Customer creates review
  const review = await generate_random_shopping_mall_customer_reviews_create(
    customerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
        shopping_mall_order_id: order.id,
        rating: 4,
        content: "Initial review content for testing snapshot preservation",
      },
    },
  );
  typia.assert(review);
  // Step 6: Customer edits review multiple times to create snapshots
  const updatedReview1 =
    await api.functional.shoppingMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: 5,
          content: "Updated review - excellent product after more use!",
        } satisfies IShoppingMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview1);
  const updatedReview2 =
    await api.functional.shoppingMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: 3,
          content: "Changed my mind - some issues found",
        } satisfies IShoppingMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview2);
  const updatedReview3 =
    await api.functional.shoppingMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: review.id,
        body: {
          rating: 4,
          content: "Final update - resolved most issues, good product overall",
        } satisfies IShoppingMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview3);
  // Step 7: Customer soft-deletes the review
  await api.functional.shoppingMall.customer.reviews.erase(customerConnection, {
    reviewId: review.id,
  });
  // Step 8: Administrator retrieves snapshots for the deleted review
  const snapshots =
    await api.functional.shoppingMall.administrator.reviews.snapshots.index(
      adminConnection,
      {
        reviewId: review.id,
        body: {
          page: 1,
          limit: 10,
        } satisfies IShoppingMallReviewSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  // Step 9: Validate snapshot preservation
  TestValidator.predicate(
    "snapshots accessible after review deletion",
    snapshots.data.length > 0,
  );
  TestValidator.equals(
    "correct number of snapshots created",
    snapshots.data.length,
    3,
  );
  // Verify snapshots are in chronological order (oldest first)
  for (let i = 1; i < snapshots.data.length; i++) {
    const prev = new Date(snapshots.data[i - 1].created_at).getTime();
    const curr = new Date(snapshots.data[i].created_at).getTime();
    TestValidator.predicate(
      `snapshot ${i} is newer than snapshot ${i - 1}`,
      prev <= curr,
    );
  }
  // Verify each snapshot has required fields
  snapshots.data.forEach((snapshot, index) => {
    TestValidator.predicate(
      `snapshot ${index + 1} has valid rating (1-5)`,
      snapshot.rating >= 1 && snapshot.rating <= 5,
    );
    TestValidator.predicate(
      `snapshot ${index + 1} has created_at`,
      snapshot.created_at !== undefined,
    );
  });
  // Verify pagination works for deleted reviews
  TestValidator.equals(
    "pagination current page is 1",
    snapshots.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination records matches data length",
    snapshots.pagination.records >= snapshots.data.length,
  );
}

