export async function test_api_product_variant_stock_out_of_stock(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {});
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Create category (as administrator)
  const category =
    await generate_random_shopping_mall_administrator_categories_create(
      adminConnection,
      {},
    );
  // 4. Create product (as seller)
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        categoryId: category.id,
        basePrice: typia.random<
          number & tags.Minimum<1> & tags.Maximum<10000>
        >(),
      },
    },
  );
  typia.assert(product);
  // 5. Create variant with specific SKU and options
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          optionValues: {
            color: RandomGenerator.pick([
              "Red",
              "Blue",
              "Green",
              "Black",
            ] as const),
            size: RandomGenerator.pick(["Small", "Medium", "Large"] as const),
          },
        },
      },
    );
  typia.assert(variant);
  // 6. Create inventory record: +50 (restock)
  await generate_random_shopping_mall_seller_variants_inventory_records_create(
    sellerConnection,
    {
      params: { variantId: variant.id },
      body: {
        quantity_change: 50,
        reason: "Initial stock from supplier",
      },
    },
  );
  // 7. Create inventory record: -50 (deduction to bring stock to 0)
  await generate_random_shopping_mall_seller_variants_inventory_records_create(
    sellerConnection,
    {
      params: { variantId: variant.id },
      body: {
        quantity_change: -50,
        reason: "Inventory adjustment - order fulfillment",
      },
    },
  );
  // 8. Administrator checks stock information
  const stock =
    await api.functional.shoppingMall.administrator.variants.stock.at(
      adminConnection,
      {
        variantId: variant.id,
      },
    );
  typia.assert(stock);
  // 9. Validations
  TestValidator.equals("variant id matches", stock.id, variant.id);
  TestValidator.equals("sku code matches", stock.skuCode, variant.skuCode);
  TestValidator.equals("stock quantity is zero", stock.stockQuantity, 0);
  TestValidator.equals(
    "availability is out_of_stock",
    stock.availability,
    "out_of_stock",
  );
  TestValidator.predicate(
    "option values match",
    stock.optionValues.color === variant.optionValues.color &&
      stock.optionValues.size === variant.optionValues.size,
  );
}

