export async function test_api_cancellation_request_seller_rejection(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: "https://test.com/admin",
      referrer: "https://test.com",
    },
  });
  const category =
    await generate_random_shopping_mall_administrator_categories_create(
      adminConnection,
      { body: { name: RandomGenerator.name(1) } },
    );
  typia.assert(category);
  // 2. Seller setup - register and create product with variant
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(1),
      href: "https://test.com/seller",
      referrer: "https://test.com",
    },
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(2),
        description: RandomGenerator.paragraph(),
        categoryId: category.id,
        basePrice: typia.random<
          number &
            tags.Type<"uint32"> &
            tags.Minimum<1000> &
            tags.Maximum<100000>
        >(),
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          skuCode: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          optionValues: {
            color: RandomGenerator.pick(["Red", "Blue", "Green"] as const),
          },
        },
      },
    );
  typia.assert(variant);
  // Add inventory for the variant
  const inventory =
    await generate_random_shopping_mall_seller_variants_inventory_records_create(
      sellerConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantity_change: 100,
          reason: "Initial inventory for testing",
        },
      },
    );
  typia.assert(inventory);
  // 3. Customer setup - register and create address
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: "https://test.com/customer",
      referrer: "https://test.com",
    },
  });
  const address = await generate_random_shopping_mall_customer_addresses_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        street_address: RandomGenerator.name(2) + " Street",
        city: "Test City",
        state_province: "Test State",
        postal_code: "12345",
        country: "Test Country",
        is_default: true,
      },
    },
  );
  typia.assert(address);
  // 4. Customer adds item to cart
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          variant_id: variant.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        },
      },
    );
  typia.assert(cartItem);
  // 5. Customer places order
  const order = await generate_random_shopping_mall_customer_checkout_create(
    customerConnection,
    { body: { address_id: address.id } },
  );
  typia.assert(order);
  // 6. Customer creates cancellation request
  // Note: After checkout, order items are created. We need to create a cancellation request
  // for an order item. Since the cancellation request creation requires an order item ID,
  // we use the generation utility which handles the internal logic.
  const cancellationRequest =
    await generate_random_shopping_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          orderItemId: { id: order.id } as IShoppingMallOrderItem,
          reason: "Customer requested cancellation for testing",
        },
      },
    );
  typia.assert(cancellationRequest);
  // Store original status for comparison
  const originalStatus = cancellationRequest.status;
  TestValidator.equals("initial status is pending", originalStatus, "pending");
  TestValidator.equals(
    "seller is null initially",
    cancellationRequest.seller,
    null,
  );
  TestValidator.equals(
    "responded_at is null initially",
    cancellationRequest.respondedAt,
    null,
  );
  // 7. Seller rejects the cancellation request
  const rejection =
    await api.functional.shoppingMall.seller.cancellation_requests.respond(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "rejected",
        } satisfies IShoppingMallCancellationRequest.IRespond,
      },
    );
  typia.assert(rejection);
  // 8. Validate rejection response
  TestValidator.equals(
    "cancellation request status is rejected",
    rejection.status,
    "rejected",
  );
  TestValidator.predicate("seller is populated", rejection.seller !== null);
  TestValidator.predicate(
    "responded_at is set",
    rejection.respondedAt !== null,
  );
  TestValidator.equals(
    "seller matches the rejecting seller",
    rejection.seller?.id,
    sellerAuth.id,
  );
}

