    });
  // 4. Query with pagination (sequential await)
  const data =
    await MyGlobal.prisma.shopping_mall_product_snapshot_skuses.findMany({
      where: whereInput,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
