      product: {
        deleted_at: null,
        seller: {
          suspended: false,
          banned: false,
        },
      },
    },
  });
  // Transform results
  const data = await ArrayUtil.asyncMap(
    items,
    ShoppingMallWishlistItemAtSummaryTransformer.transform,
  );
  return {
    data,
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
}

