export async function postShoppingMallAdministratorOrderItemsOrderItemIdForceRefund(props: {
  administrator: AdministratorPayload;
  orderItemId: string & tags.Format<"uuid">;
  body: IShoppingMallOrderItem.IForceRefund;
}): Promise<IShoppingMallOrderItem> {
  const now = new Date();
  // Execute all operations in transaction
  const orderItem = await MyGlobal.prisma.$transaction(async (tx) => {
    // Find the order item
    const item = await tx.shopping_mall_order_items.findUniqueOrThrow({
      where: { id: props.orderItemId },
      select: {
        id: true,
        shopping_mall_order_id: true,
        shopping_mall_product_variant_id: true,
        status: true,
        quantity: true,
      },
    });
    // Validate status - cannot force refund if already cancelled or refunded
    if (item.status === "cancelled" || item.status === "refunded") {
      throw new HttpException(
        `Cannot force refund order item that is already ${item.status}`,
        400,
      );
    }
    // Check for existing pending refund request
    const existingRefundRequest =
      await tx.shopping_mall_refund_requests.findUnique({
        where: { shopping_mall_order_item_id: props.orderItemId },
      });
    // Close pending refund request if exists
    if (existingRefundRequest && existingRefundRequest.status === "pending") {
      await tx.shopping_mall_refund_requests.update({
        where: { id: existingRefundRequest.id },
        data: {
          status: "approved",
          responded_at: now,
        },
      });
    }
    // Create inventory record to restore stock
    await tx.shopping_mall_inventory_records.create({
      data: {
        id: v4(),
        variant_id: item.shopping_mall_product_variant_id,
        quantity_change: item.quantity,
        reason: `Administrator force refund: ${props.body.reason}`,
        created_at: now,
      },
    });
    // Update order item status to refunded
    await tx.shopping_mall_order_items.update({
      where: { id: props.orderItemId },
      data: {
        status: "refunded",
        updated_at: now,
      },
    });
    // Recalculate order status based on all items
    const allOrderItems = await tx.shopping_mall_order_items.findMany({
      where: { shopping_mall_order_id: item.shopping_mall_order_id },
      select: { status: true },
    });
    const statuses = allOrderItems.map((i) => i.status);
    let newOrderStatus: string;
    if (statuses.every((s) => s === "refunded")) {
      newOrderStatus = "refunded";
    } else if (statuses.every((s) => s === "cancelled")) {
      newOrderStatus = "cancelled";
    } else if (statuses.every((s) => s === "delivered")) {
      newOrderStatus = "delivered";
    } else if (statuses.every((s) => s === "shipped")) {
      newOrderStatus = "shipped";
    } else if (statuses.every((s) => s === "paid")) {
      newOrderStatus = "paid";
    } else {
      newOrderStatus = "partially_completed";
    }
    await tx.shopping_mall_orders.update({
      where: { id: item.shopping_mall_order_id },
      data: {
        status: newOrderStatus,
        updated_at: now,
      },
    });
    return item;
  });
  // Fetch and return the updated order item with all relations
  const updatedItem =
    await MyGlobal.prisma.shopping_mall_order_items.findUniqueOrThrow({
      where: { id: props.orderItemId },
      ...ShoppingMallOrderItemTransformer.select(),
    });
  return await ShoppingMallOrderItemTransformer.transform(updatedItem);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallRefundRequestStatistic } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequestStatistic";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function getShoppingMallSellerRefundRequestStatistics(props: {
  seller: SellerPayload;
}): Promise<IShoppingMallRefundRequestStatistic> {
  // Query refund requests grouped by status, filtered by seller through order items
  const statusCounts =
    await MyGlobal.prisma.shopping_mall_refund_requests.groupBy({
      by: ["status"],
      where: {
        orderItem: {
          shopping_mall_seller_id: props.seller.id,
        },
      },
      _count: {
        status: true,
      },
    });
  // Initialize counts
  let pending = 0;
  let approved = 0;
  let rejected = 0;
  // Aggregate counts by status
  for (const record of statusCounts) {
    const count = record._count.status;
    if (record.status === "pending") {
      pending = count;
    } else if (record.status === "approved") {
      approved = count;
    } else if (record.status === "rejected") {
      rejected = count;
    }
  }
  const total = pending + approved + rejected;
  return {
    total,
    pending,
    approved,
    rejected,
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAddress";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";
import { ShoppingMallAddressTransformer } from "../transformers/ShoppingMallAddressTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putShoppingMallCustomerAddressesAddressIdDefault(props: {
  customer: CustomerPayload;
  addressId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallAddress> {
  // Find the address to verify ownership and existence
  const address = await MyGlobal.prisma.shopping_mall_addresses.findUnique({
    where: { id: props.addressId },
    select: {
      id: true,
      shopping_mall_customer_id: true,
      deleted_at: true,
    },
  });
  // Address not found
  if (!address) {
    throw new HttpException("Address not found", 404);
  }
  // Ownership check - must belong to authenticated customer
  if (address.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden", 403);
  }
  // Soft-deleted addresses cannot be set as default
  if (address.deleted_at !== null) {
    throw new HttpException("Address not found", 404);
  }
  // Transaction to atomically update default status
  await MyGlobal.prisma.$transaction([
    // Unset previous default (if any exists)
    MyGlobal.prisma.shopping_mall_addresses.updateMany({
      where: {
        shopping_mall_customer_id: props.customer.id,
        is_default: true,
      },
      data: {
        is_default: false,
        updated_at: new Date(),
      },
    }),
    // Set new default
    MyGlobal.prisma.shopping_mall_addresses.update({
      where: { id: props.addressId },
      data: {
        is_default: true,
        updated_at: new Date(),
      },
    }),
  ]);
  // Fetch and return updated address with full customer relation
  const updated =
    await MyGlobal.prisma.shopping_mall_addresses.findUniqueOrThrow({
      where: { id: props.addressId },
      ...ShoppingMallAddressTransformer.select(),
    });
  return ShoppingMallAddressTransformer.transform(updated);
}

