@Controller("/shoppingMall/seller/variants/:variantId/inventory-records")
export class ShoppingmallSellerVariantsInventory_recordsController {
  /**
   * Create a new manual inventory record for a product variant.
   *
   * This operation allows sellers to manually adjust inventory levels for variants they own. Sellers can add stock (positive quantity_change for restocking from suppliers, initial stock setup, or inventory corrections) or subtract stock (negative quantity_change for damaged goods, lost items, inventory corrections, or expired products). Each manual adjustment requires a reason documenting why the change was made, providing transparency and supporting audit trails.
   *
   * The inventory record is immutable once created and becomes part of the permanent audit trail. Current stock for any variant is calculated by summing all inventory records, ensuring accurate and traceable stock levels throughout the product lifecycle.
   *
   * Sellers can only adjust inventory for variants of their own products. The system validates that negative adjustments do not result in negative stock levels. Manual inventory adjustments are not permitted for variants belonging to suspended seller accounts.
   *
   * This operation creates only manual inventory records. Automatic inventory changes (triggered by order placement, cancellations, or refunds) are handled by the system internally and do not use this endpoint.
   *
   * @param connection
   * @param variantId Unique identifier of the product variant whose inventory is being adjusted. The seller must own this variant through their product to perform the adjustment.
   * @param body Inventory adjustment details including the quantity change and reason for the adjustment
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Implementation Guide:
   *
   * 1. **Authentication & Authorization**:
   *    - Extract authenticated seller from session
   *    - Query variant by variantId with include: { product: { select: { shopping_mall_seller_id: true } } }
   *    - Verify variant.product.shopping_mall_seller_id matches authenticated seller.id
   *    - If not owned, return 403 Forbidden
   *
   * 2. **Validation**:
   *    - Validate quantity_change is a non-zero integer
   *    - Validate reason is non-empty text
   *    - If quantity_change is negative:
   *      - Calculate current stock: SUM all inventory_records.quantity_change where variant_id = variantId
   *      - Verify current_stock + quantity_change >= 0
   *      - If insufficient stock, return 400 Bad Request with error
   *
   * 3. **Business Logic**:
   *    - Create new inventory_record with:
   *      - variant_id = variantId (from path)
   *      - seller_id = authenticated seller.id (manual adjustment marker)
   *      - quantity_change = request body value
   *      - reason = request body value (seller-provided explanation)
   *      - order_id, cancellation_request_id, refund_request_id = null (manual entry)
   *      - created_at = current timestamp
   *    - Return created record
   *
   * 4. **Database Transaction**:
   *    - Use atomic transaction to ensure consistency
   *    - No cached stock value to update (stock is calculated on-demand)
   *
   * 5. **Edge Cases**:
   *    - Variant must exist (404 if not found)
   *    - Variant must not be soft-deleted (deleted_at is null)
   *    - Seller account must not be suspended or banned
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("variantId")
    variantId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallInventoryRecord.ICreate,
  ): Promise<IShoppingMallInventoryRecord> {
    try {
      return await postShoppingMallSellerVariantsVariantIdInventoryRecords({
        seller,
        variantId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve the complete inventory history (audit trail) for a specific product variant.
   *
   * This endpoint provides sellers with a chronological view of all inventory movements for a variant, including manual restocks, manual adjustments, order-triggered deductions, and automatic restorations from cancellations or refunds. Each record documents the quantity change (positive for additions, negative for deductions), reason, and timestamp.
   *
   * The inventory history serves as an immutable audit trail for stock management, dispute resolution, and transparency. Records cannot be deleted or modified after creation, ensuring complete traceability.
   *
   * **Authorization**: Only the seller who owns the product containing this variant can access its inventory history.
   *
   * **Related Operations**:
   * - POST /variants/{variantId}/inventory-records - Create a manual inventory adjustment (restock or subtraction)
   * - GET /variants/{variantId} - View variant details including current stock calculation
   *
   * **Database**: Records are stored in shopping_mall_inventory_records with references to shopping_mall_product_variants. Current stock is calculated by summing all inventory_records for the variant.
   *
   * @param connection
